# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM TOPLUMUNU YÖNLENDİREN İLKELER: KARDEŞLİK (UHUVVET)</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Uhuvvet (İslam Kardeşliği) Esasları</text>\n  <rect x="42" y="84" width="280" height="40" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="182" y="101" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">"Müminler ancak kardeştirler..."</text>\n  <text x="182" y="117" text-anchor="middle" font-size="10.5" fill="#1d4ed8">(Hucurât Suresi, 10. Ayet)</text>\n  <text x="42" y="144" font-size="11" fill="#1e3a8a">• Soy, kabile, ırk ve renk üstünlüğünü reddeder.</text>\n  <text x="42" y="166" font-size="11" fill="#1e3a8a">• Tevhid ve takva ortak paydasına dayanır.</text>\n  <text x="42" y="188" font-size="11" fill="#1e3a8a">• Müslümanları "kenetlenmiş bir bina" ve</text>\n  <text x="50" y="204" font-size="11" fill="#1e3a8a">"tek bir beden" gibi birbirine bağlar.</text>\n  <text x="42" y="226" font-size="11" font-weight="bold" fill="#1d4ed8">• Îsâr: Kendi ihtiyacı varken kardeşini tercih etmek</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Tarihî Zirve: Muâhât (Medine, 622)</text>\n  <rect x="378" y="84" width="125" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="440" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">MUHACİRLER</text>\n  <text x="440" y="120" text-anchor="middle" font-size="10" fill="#14532d">(Mekke\'den Göç Edenler)</text>\n  <rect x="530" y="84" width="125" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="592" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">ENSAR</text>\n  <text x="592" y="120" text-anchor="middle" font-size="10" fill="#14532d">(Medineli Yardımseverler)</text>\n  <line x1="503" y1="106" x2="530" y2="106" stroke="#16a34a" stroke-width="3"/>\n  <text x="378" y="150" font-size="11" fill="#14532d">• Hicret sonrası Hz. Peygamber tarafından her</text>\n  <text x="386" y="166" font-size="11" fill="#14532d">Muhacir bir Ensar ailesiyle kardeş ilan edildi.</text>\n  <text x="378" y="188" font-size="11" fill="#14532d">• Maddi-manevi paylaşım ve sosyal bütünleşme</text>\n  <text x="386" y="204" font-size="11" fill="#14532d">ile İslam medeniyetinin ilk toplumu kuruldu.</text>\n  <text x="378" y="226" font-size="11" font-weight="bold" fill="#15803d">• Kültürümüzde yansıması: Ahilik ve Fütüvvet</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YARDIMLAŞMA VE DAYANIŞMA KURUMLARI (İNFAK VE ZEKÂT)</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">1. İnfak ve Sadaka</text>\n  <text x="38" y="96" font-size="11" fill="#78350f">• <tspan font-weight="bold">İnfak:</tspan> Allah rızası için maldan</text>\n  <text x="46" y="112" font-size="11" fill="#78350f">harcama yapmak (farz + nafile).</text>\n  <text x="38" y="134" font-size="11" fill="#78350f">• <tspan font-weight="bold">Sadaka:</tspan> Maddi ve manevi her</text>\n  <text x="46" y="150" font-size="11" fill="#78350f">türlü iyilik (tebessüm dahil).</text>\n  <rect x="38" y="170" width="178" height="52" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="127" y="191" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Sadaka-i Fıtır (Fitre):</text>\n  <text x="127" y="208" text-anchor="middle" font-size="10" fill="#78350f">Ramazan\'da verilen vacip sadaka</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">2. Zekât İbadeti</text>\n  <text x="260" y="96" font-size="11" fill="#1e3a8a">• Zenginlerin yılda bir kez</text>\n  <text x="268" y="112" font-size="11" fill="#1e3a8a">mallarının belirli oranını</text>\n  <text x="268" y="128" font-size="11" fill="#1e3a8a">yoksullara vermesidir (Farz).</text>\n  <text x="260" y="150" font-size="11" fill="#1e3a8a">• Servetin belli ellerde</text>\n  <text x="268" y="166" font-size="11" fill="#1e3a8a">toplanmasını önler.</text>\n  <rect x="260" y="178" width="178" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="349" y="198" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Zengin-yoksul uçurumunu</text>\n  <text x="349" y="213" text-anchor="middle" font-size="10.5" fill="#1e3a8a">kapatır, sevgi bağı kurar.</text>\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">3. Karz-ı Hasen</text>\n  <text x="483" y="96" font-size="11" fill="#581c87">• "Güzel ödünç" demektir.</text>\n  <text x="483" y="118" font-size="11" fill="#581c87">• İhtiyaç sahibine <tspan font-weight="bold">hiçbir faiz</tspan></text>\n  <text x="491" y="134" font-size="11" fill="#581c87"><tspan font-weight="bold">veya dünyevi menfaat</tspan></text>\n  <text x="491" y="150" font-size="11" fill="#581c87">beklemeden verilen borçtur.</text>\n  <rect x="483" y="170" width="178" height="52" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="572" y="191" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">Tefeciliği ve faizi önler,</text>\n  <text x="572" y="208" text-anchor="middle" font-size="10" fill="#581c87">onurlu dayanışmayı sağlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SADAKA-İ CARİYE VE VAKIF MEDENİYETİ UYGULAMALARI</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Sadaka-i Cariye ve Vakıf Ruhu</text>\n  <text x="42" y="96" font-size="11" fill="#14532d">• <tspan font-weight="bold">Sadaka-i Cariye:</tspan> İnsanın ölümünden sonra da</text>\n  <text x="50" y="112" font-size="11" fill="#14532d">amel defterine sevap yazdırmaya devam eden</text>\n  <text x="50" y="128" font-size="11" fill="#14532d">kalıcı hayır eserleri, faydalı ilim ve salih evlat.</text>\n  <text x="42" y="152" font-size="11" fill="#14532d">• <tspan font-weight="bold">Vakıf:</tspan> Kişinin helal malını alınıp satılamaz</text>\n  <text x="50" y="168" font-size="11" fill="#14532d">şekilde kamu yararına ebedî olarak tahsis etmesi.</text>\n  <rect x="42" y="186" width="280" height="40" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="182" y="204" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Cami, medrese, darüşşifa (hastane), imaret</text>\n  <text x="182" y="219" text-anchor="middle" font-size="10.5" fill="#14532d">(aşevi), kervansaray, su kemeri, çeşme, kütüphane</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">İncelikli Dayanışma Geleneklerimiz</text>\n  <rect x="378" y="84" width="280" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="388" y="102" font-size="11" font-weight="bold" fill="#1e3a8a">1. Zimem Defteri (Veresiye Defteri)</text>\n  <text x="388" y="118" font-size="10.5" fill="#1e40af">Mahalle bakkalındaki yoksul borçlarının gizlice silinmesi</text>\n  <rect x="378" y="136" width="280" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="388" y="154" font-size="11" font-weight="bold" fill="#1e3a8a">2. Sadaka Taşları</text>\n  <text x="388" y="170" font-size="10.5" fill="#1e40af">Veren elin alan eli görmediği, onur koruyan yardımlaşma</text>\n  <rect x="378" y="188" width="280" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="388" y="206" font-size="11" font-weight="bold" fill="#1e3a8a">3. Avarız Vakıfları ve Orta Sandıkları</text>\n  <text x="388" y="222" text-anchor="middle" font-size="10.5" fill="#1e40af">Afet, hastalık ve olağanüstü durumlar için sosyal fon</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
